#pragma once
/**
 * @file RunTimingRunEnd.hpp
 * @brief Run-end report of the run's wall clock: the epoch-loop wall and the D0/D0b section timers.
 *
 * The run-end reports defined in RunTimingRunEnd.cpp; each is a row of kNetworkRunEndReports
 * (network/runend/RunEnd.hpp).
 */

namespace GnssProcessor {

// ---- Run-end reports (generated by scripts/nom_td_cut.py) ----

struct NetworkRunEndView;

/**
 * @brief Run-end report: run timing: the epoch-loop wall, the D0 and D0b section timers.
 *
 * The epoch-loop wall line (every run), then, with network.trace_section_timers, the D0
 * section-timer run totals, the invariant-carry driver's per-op split and census on a
 * carry_invariant run, and the D0b ranking of the `other` sub-blocks. Every figure is
 * wall clock.
 *
 * Gate: each section under its own condition, as in the teardown: always;
 * `sec_timers_on`.
 *
 * @param v The run at its end (network/runend/RunEnd.hpp).
 * @return 0 (this report does not set the exit code).
 */
int networkRunTimingRunEnd(const NetworkRunEndView& v);

// ---- End of the run-end reports ----

} // namespace GnssProcessor
